259:   public static final class OwnedCacheListener implements TestExecutionListener, Ordered {
260:     private TestContext capturedTestContext;
261:     private ConfigurableApplicationContext capturedApplicationContext;
262: 
263:     @Override
264:     public int getOrder() {
265:       // afterTestClass runs in reverse: Zonky 3800, this owner 3500, DirtiesContext 3000.
