269:     @Override
270:     public void prepareTestInstance(TestContext testContext) {
271:       assertThat(testContext.getTestClass()).isSameAs(GuidedServiceTransportFaultIT.class);
272:       var instance = (GuidedServiceTransportFaultIT) testContext.getTestInstance();
273:       assertThat(testContext.getApplicationContext()).isSameAs(instance.context);
274:       ownedTestContext = testContext;
275:       capturedTestContext = testContext;
276:       capturedApplicationContext = instance.context;
277:     }
278: 
279:     @Override
280:     public void afterTestClass(TestContext testContext) throws Exception {
281:       try {
282:         assertThat(testContext.getTestClass()).isSameAs(GuidedServiceTransportFaultIT.class);
283:         assertThat(testContext).isSameAs(capturedTestContext);
284:         assertThat(ownedTestContext).isSameAs(capturedTestContext);
285:         assertThat(ownedContext).isSameAs(capturedApplicationContext);
286:         assertThat(testContext.getApplicationContext()).isSameAs(capturedApplicationContext);
287:         close();
288:       } finally {
289:         capturedTestContext = null;
290:         capturedApplicationContext = null;
291:         ownedTestContext = null;
292:         ownedContext = null;
293:       }
294:     }
295:   }
