1274:             for (Throwable cleanup : cleanupFailures) {
1275:               addSuppressedDistinct(primary, cleanup);
1276:             }
1277:           } else if (!cleanupFailures.isEmpty()) {
1278:             Throwable first = cleanupFailures.getFirst();
1279:             for (int i = 1; i < cleanupFailures.size(); i++) {
1280:               addSuppressedDistinct(first, cleanupFailures.get(i));
1281:             }
1282:             if (first instanceof Exception failure) {
1283:               throw failure;
1284:             }
1285:             if (first instanceof Error failure) {
1286:               throw failure;
1287:             }
1288:             throw new AssertionError(first);
1289:           }
1290:         } finally {
1291:           if (interrupted) {
1292:             Thread.currentThread().interrupt();
1293:           }
1294:         }
1295:       }
1296:     }
1297:   }
