1364:   private static Map<String, Object> heldRowConnectionSettings(
1365:       java.sql.Connection connection, DriverManagerDataSource source, JdbcTemplate jdbc)
1366:       throws java.sql.SQLException {
1367:     var settings = new java.util.LinkedHashMap<String, Object>();
1368:     settings.put("jdbcNetworkTimeoutMillis", connection.getNetworkTimeout());
1369:     settings.put("jdbcTemplateQueryTimeoutSeconds", jdbc.getQueryTimeout());
1370:     var properties = new java.util.Properties();
1371:     if (source.getConnectionProperties() != null) {
1372:       properties.putAll(source.getConnectionProperties());
1373:     }
1374:     var infos =
1375:         java.sql.DriverManager.getDriver(source.getUrl())
1376:             .getPropertyInfo(source.getUrl(), properties);
1377:     for (var info : infos) {
1378:       if (java.util.Set.of("connectTimeout", "socketTimeout").contains(info.name)) {
1379:         settings.put(info.name, info.value);
1380:       }
1381:     }
1382:     try (var statement = connection.createStatement()) {
1383:       settings.put("newStatementQueryTimeoutSeconds", statement.getQueryTimeout());
1384:       try (var pid = statement.executeQuery("SELECT pg_backend_pid()")) {
1385:         assertThat(pid.next()).isTrue();
1386:         settings.put("pid", pid.getInt(1));
1387:       }
1388:       for (String name :
1389:           List.of("lock_timeout", "statement_timeout", "idle_in_transaction_session_timeout")) {
1390:         try (var setting = statement.executeQuery("SHOW " + name)) {
1391:           assertThat(setting.next()).isTrue();
1392:           settings.put(name, setting.getString(1));
1393:         }
1394:       }
1395:     }
1396:     return settings;
1397:   }
