1399:   private static final class HeldRowTrace {
1400:     final DriverManagerDataSource source;
1401:     final JdbcTemplate jdbc;
1402:     final SourceStopOwner owner;
1403:     final CountDownLatch observed = new CountDownLatch(1);
1404:     final AtomicReference<Map<String, Object>> settings = new AtomicReference<>();
1405:     final AtomicReference<Throwable> observationFailure = new AtomicReference<>();
1406:     final AtomicInteger completionStatus = new AtomicInteger(-1);
1407:     volatile Thread caller;
1408:     volatile String sessionId;
1409:     volatile Scenario scenario;
1410:     volatile boolean observeReconciliation;
1411: 
1412:     HeldRowTrace(DriverManagerDataSource source, JdbcTemplate jdbc, SourceStopOwner owner) {
1413:       this.source = source;
1414:       this.jdbc = jdbc;
1415:       this.owner = owner;
1416:     }
1417: 
1418:     boolean target() {
1419:       // Real headers are emitted only after consume/read/release and accepted dispatch bytes.
1420:       // This also captures honest HTTP-timeout reconciliation if a prerequisite observer is slow.
1421:       return Thread.currentThread() == caller
1422:           && (observeReconciliation || scenario != null && scenario.headers.getCount() == 0);
1423:     }
1424:   }
