1426:   private static final class HeldRowTransactionManager extends DataSourceTransactionManager {
1427:     private final HeldRowTrace trace;
1428: 
1429:     HeldRowTransactionManager(DataSource source, HeldRowTrace trace) {
1430:       super(source);
1431:       this.trace = trace;
1432:     }
1433: 
1434:     @Override
1435:     protected void doBegin(
1436:         Object transaction, org.springframework.transaction.TransactionDefinition definition) {
1437:       super.doBegin(transaction, definition);
1438:       if (!trace.target()) {
1439:         return;
1440:       }
1441:       try {
1442:         var holder =
1443:             (org.springframework.jdbc.datasource.ConnectionHolder)
1444:                 org.springframework.transaction.support.TransactionSynchronizationManager
1445:                     .getResource(trace.source);
1446:         var settings = heldRowConnectionSettings(holder.getConnection(), trace.source, trace.jdbc);
1447:         settings.put("definitionTimeout", definition.getTimeout());
1448:         settings.put("managerDefaultTimeout", getDefaultTimeout());
1449:         settings.put("transactionDeadline", holder.hasTimeout());
1450:         trace.settings.set(settings);
1451:       } catch (Exception | Error observationFailure) {
1452:         // Observation does not replace/reject the real callback or manufacture a SQL failure.
1453:         trace.observationFailure.compareAndSet(null, observationFailure);
1454:       } finally {
1455:         trace.observed.countDown();
1456:       }
1457:     }
1458: 
1459:     @Override
1460:     protected void prepareSynchronization(
1461:         org.springframework.transaction.support.DefaultTransactionStatus status,
1462:         org.springframework.transaction.TransactionDefinition definition) {
1463:       super.prepareSynchronization(status, definition);
1464:       if (trace.target() && status.isNewSynchronization()) {
1465:         org.springframework.transaction.support.TransactionSynchronizationManager
1466:             .registerSynchronization(
1467:                 new org.springframework.transaction.support.TransactionSynchronization() {
1468:                   @Override
1469:                   public int getOrder() {
1470:                     // Pinned Spring sorts ascending; production stop synchronization is LOWEST.
1471:                     return Ordered.HIGHEST_PRECEDENCE;
1472:                   }
1473: 
1474:                   @Override
1475:                   public void afterCompletion(int completionStatus) {
1476:                     trace.completionStatus.set(completionStatus);
1477:                     if (completionStatus != STATUS_COMMITTED) {
1478:                       return;
1479:                     }
1480:                     try {
1481:                       // Real committed cut only, before the later original callback schedules stop.
1482:                       trace.owner.expect(trace.sessionId);
1483:                     } catch (Throwable observationFailure) {
1484:                       // Spring logs/catches callback failures; retain a sticky test failure
1485:                       // explicitly.
1486:                       if (!trace.observationFailure.compareAndSet(null, observationFailure)) {
1487:                         addSuppressedDistinct(trace.observationFailure.get(), observationFailure);
1488:                       }
1489:                     }
1490:                   }
1491:                 });
1492:       }
1493:     }
1494:   }
