2211:   /** Owns the two actual operations, not the unexposed outer common-pool Future. */
2212:   private static final class SourceStopOwner {
2213:     private static final ThreadLocal<SourceStopOwner> CONFIRMATION = new ThreadLocal<>();
2214:     final DataSource source;
2215:     final AtomicInteger initiated = new AtomicInteger(), finished = new AtomicInteger();
2216:     final AtomicInteger confirmationCalls = new AtomicInteger(), drains = new AtomicInteger();
2217:     final AtomicReference<Throwable> failure = new AtomicReference<>(),
2218:         guardFailure = new AtomicReference<>();
2219:     final CountDownLatch completed = new CountDownLatch(1), settled = new CountDownLatch(1);
2220:     final AtomicBoolean senderReserved = new AtomicBoolean();
2221:     final OperationGate confirmationGate = new OperationGate();
2222:     volatile boolean gateConfirmation;
2223:     volatile boolean expected;
2224:     volatile String sessionId;
2225:     volatile Thread executingThread;
2226: 
2227:     SourceStopOwner(DataSource source) {
2228:       this.source = source;
2229:       STOP_OWNERS.add(this);
2230:     }
2231: 
2232:     synchronized void expect(String id) {
2233:       if (expected) {
2234:         assertThat(sessionId).isEqualTo(id);
2235:         return;
2236:       }
2237:       sessionId = id;
2238:       expected = true;
2239:     }
2240: 
2241:     void rejectGuard(Throwable problem) {
2242:       guardFailure.compareAndSet(null, problem);
2243:       // Rejection is observable failure, never genuine original-operation completion.
2244:       settled.countDown();
2245:     }
2246: 
2247:     void send(GuidedDispatchService sender, ObjectNode context, String reason) {
2248:       try {
2249:         assertThat(expected).as("actual stop must have a preregistered owner").isTrue();
2250:         assertThat(context.path("sessionId").asText()).isEqualTo(sessionId);
2251:         assertThat(CONFIRMATION.get()).isNull();
2252:         assertThat(senderReserved.compareAndSet(false, true)).isTrue();
2253:       } catch (RuntimeException | Error problem) {
2254:         rejectGuard(problem);
2255:         throw problem;
2256:       }
2257:       boolean confirmationExpected = false;
2258:       executingThread = Thread.currentThread();
2259:       try {
2260:         // No guard/count rejection intervenes between this original-call entry and forwarding.
2261:         initiated.incrementAndGet();
2262:         sender.stop(context, reason);
2263:         CONFIRMATION.set(this);
2264:         confirmationExpected = true;
2265:       } catch (RuntimeException | Error problem) {
2266:         failure.compareAndSet(null, problem);
2267:         CONFIRMATION.remove();
2268:         throw problem;
2269:       } finally {
2270:         finished.incrementAndGet();
2271:         if (!confirmationExpected) {
2272:           completed.countDown();
2273:           settled.countDown();
2274:         }
2275:       }
2276:     }
2277: 
2278:     boolean operationsComplete() {
2279:       return guardFailure.get() == null && (!expected || completed.getCount() == 0);
2280:     }
2281: 
2282:     void observeCompletion() throws InterruptedException {
2283:       completed.await();
2284:     }
2285: 
2286:     void drainUninterruptibly() {
2287:       if (!expected && guardFailure.get() == null) {
2288:         return;
2289:       }
2290:       drains.incrementAndGet();
2291:       boolean interrupted = Thread.interrupted();
2292:       try {
2293:         while (true) {
2294:           try {
2295:             settled.await();
2296:             Throwable rejected = guardFailure.get();
2297:             if (rejected != null) {
2298:               // The real-completion latch remains pending for rejected/unstarted work.
2299:               // Refuse proxy/context destruction rather than assert that ownership was drained.
2300:               // A fresh guard diagnostic preserves the cause without try-with-resources
2301:               // attempting to self-suppress the same rejected Throwable during close.
2302:               throw new AssertionError(
2303:                   "Rejected/unstarted stop ownership cannot establish actual completion", rejected);
2304:             }
2305:             assertThat(completed.getCount()).isZero();
2306:             return;
2307:           } catch (InterruptedException interruption) {
2308:             interrupted = true;
2309:           }
2310:         }
2311:       } finally {
2312:         if (interrupted) {
2313:           Thread.currentThread().interrupt();
2314:         }
2315:       }
2316:     }
2317:   }
