2319:   private static final class TrackingTransactionTemplate extends TransactionTemplate {
2320:     private final DataSource source;
2321: 
2322:     TrackingTransactionTemplate(DataSource source) {
2323:       super(new DataSourceTransactionManager(source));
2324:       this.source = source;
2325:     }
2326: 
2327:     @Override
2328:     public <T> T execute(TransactionCallback<T> callback) {
2329:       SourceStopOwner owner = SourceStopOwner.CONFIRMATION.get();
2330:       if (owner == null) {
2331:         return super.execute(callback);
2332:       }
2333:       try {
2334:         assertThat(owner.source).isSameAs(source);
2335:         assertThat(owner.executingThread).isSameAs(Thread.currentThread());
2336:         assertThat(owner.finished.get()).isEqualTo(1);
2337:         assertThat(owner.confirmationCalls.get()).isZero();
2338:       } catch (RuntimeException | Error problem) {
2339:         SourceStopOwner.CONFIRMATION.remove();
2340:         owner.rejectGuard(problem);
2341:         throw problem;
2342:       }
2343:       if (owner.gateConfirmation) {
2344:         owner.confirmationGate.hold();
2345:       }
2346:       try {
2347:         // Original callback, manager/source, actual commit/resource cleanup, exactly once.
2348:         owner.confirmationCalls.incrementAndGet();
2349:         return super.execute(callback);
2350:       } catch (RuntimeException | Error failure) {
2351:         owner.failure.compareAndSet(null, failure);
2352:         throw failure;
2353:       } finally {
2354:         SourceStopOwner.CONFIRMATION.remove();
2355:         owner.completed.countDown();
2356:         owner.settled.countDown();
2357:       }
2358:     }
2359:   }
