2361:   private static final class OperationGate {
2362:     final CountDownLatch entered = new CountDownLatch(1), released = new CountDownLatch(1);
2363: 
2364:     void hold() {
2365:       entered.countDown();
2366:       boolean interrupted = Thread.interrupted();
2367:       try {
2368:         while (true) {
2369:           try {
2370:             released.await();
2371:             return;
2372:           } catch (InterruptedException interruption) {
2373:             interrupted = true;
2374:           }
2375:         }
2376:       } finally {
2377:         if (interrupted) {
2378:           Thread.currentThread().interrupt();
2379:         }
2380:       }
2381:     }
2382: 
2383:     void release() {
2384:       released.countDown();
2385:     }
2386:   }
