2614:   private static void joinUninterruptibly(Thread ownedThread) {
2615:     if (ownedThread == null) {
2616:       return;
2617:     }
2618:     boolean interrupted = Thread.interrupted();
2619:     try {
2620:       while (ownedThread.isAlive()) {
2621:         try {
2622:           ownedThread.join();
2623:         } catch (InterruptedException interruption) {
2624:           interrupted = true;
2625:         }
2626:       }
2627:     } finally {
2628:       if (interrupted) {
2629:         Thread.currentThread().interrupt();
2630:       }
2631:     }
2632:   }
