2634:   private static void addSuppressedDistinct(Throwable primary, Throwable addition) {
2635:     if (primary == addition) {
2636:       return;
2637:     }
2638:     for (Throwable existing : primary.getSuppressed()) {
2639:       if (existing == addition) {
2640:         return;
2641:       }
2642:     }
2643:     primary.addSuppressed(addition);
2644:   }
