2812:   /** Opaque bidirectional JDBC traffic only; no bodies, credentials or authority are recorded. */
2813:   private static final class PrivatePgRoute implements AutoCloseable {
2814:     private final InetSocketAddress target;
2815:     private final List<SourceStopOwner> owners = new java.util.concurrent.CopyOnWriteArrayList<>();
2816: 
2817:     void attach(SourceStopOwner owner) {
2818:       owners.add(owner);
2819:     }
2820: 
2821:     private final ExecutorService bridges = Executors.newVirtualThreadPerTaskExecutor();
2822:     private final Set<java.net.Socket> sockets = ConcurrentHashMap.newKeySet();
2823:     private final AtomicInteger activeTransfers = new AtomicInteger();
2824:     private final java.util.Queue<IOException> closeFailures =
2825:         new java.util.concurrent.ConcurrentLinkedQueue<>();
2826:     private volatile java.net.ServerSocket listener;
2827:     private int privatePort;
2828:     private boolean closed;
2829: 
2830:     PrivatePgRoute(String host, int port) throws IOException {
2831:       target = new InetSocketAddress(host, port);
2832:       try {
2833:         reopen();
2834:       } catch (IOException | RuntimeException | Error failure) {
2835:         bridges.shutdownNow();
2836:         throw failure;
2837:       }
2838:     }
2839: 
2840:     synchronized int port() {
2841:       return privatePort;
2842:     }
2843: 
2844:     synchronized void reopen() throws IOException {
2845:       if (closed) {
2846:         throw new IOException("Case-owned PG route is closed");
2847:       }
2848:       if (listener != null && !listener.isClosed()) {
2849:         return;
2850:       }
2851:       var server = new java.net.ServerSocket();
2852:       try {
2853:         server.setReuseAddress(true);
2854:         server.bind(new InetSocketAddress("127.0.0.1", privatePort));
2855:         privatePort = server.getLocalPort();
2856:         listener = server;
2857:         bridges.submit(() -> accept(server));
2858:       } catch (IOException | RuntimeException | Error failure) {
2859:         try {
2860:           server.close();
2861:         } catch (IOException cleanupFailure) {
2862:           failure.addSuppressed(cleanupFailure);
2863:         }
2864:         // Retain a failed-close listener so final cleanup can account for its ownership.
2865:         listener = server.isClosed() ? null : server;
2866:         throw failure;
2867:       }
2868:     }
2869: 
2870:     private void accept(java.net.ServerSocket server) {
2871:       while (!server.isClosed()) {
2872:         java.net.Socket application = null;
2873:         java.net.Socket database = null;
2874:         try {
2875:           application = server.accept();
2876:           sockets.add(application);
2877:           if (server.isClosed()) {
2878:             closeSocket(application);
2879:             return;
2880:           }
2881:           database = new java.net.Socket();
2882:           sockets.add(database);
2883:           database.connect(target, 3000);
2884:           if (server.isClosed()) {
2885:             closeSocket(application);
2886:             closeSocket(database);
2887:             return;
2888:           }
2889:           java.net.Socket app = application, pg = database;
2890:           beginTransfer(app, pg);
2891:           beginTransfer(pg, app);
2892:         } catch (IOException | java.util.concurrent.RejectedExecutionException failure) {
2893:           closeSocket(application);
2894:           closeSocket(database);
2895:           if (server.isClosed()) {
2896:             return;
2897:           }
2898:         }
2899:       }
2900:     }
2901: 
2902:     boolean idle() {
2903:       return activeTransfers.get() == 0 && sockets.isEmpty();
2904:     }
