2906:     ObjectNode countOnlyDiagnostic(int ordinal, SetupObservationStage stage, String moment) {
2907:       java.net.ServerSocket currentListener = listener;
2908:       // Independent actual scalar observations, not a coherent resource/completion snapshot.
2909:       return C.object()
2910:           .put("ordinal", ordinal)
2911:           .put("stage", stage.name())
2912:           .put("moment", moment)
2913:           .put("activeTransfers", activeTransfers.get())
2914:           .put("trackedSockets", sockets.size())
2915:           .put("closingFailures", closeFailures.size())
2916:           .put("listenerClosed", currentListener == null || currentListener.isClosed())
2917:           .put("routeClosed", closed)
2918:           .put("executorShutdown", bridges.isShutdown())
2919:           .put("executorTerminated", bridges.isTerminated());
2920:     }
2921: 
2922:     private void beginTransfer(java.net.Socket from, java.net.Socket to) {
2923:       activeTransfers.incrementAndGet();
2924:       try {
2925:         bridges.submit(() -> transfer(from, to));
2926:       } catch (java.util.concurrent.RejectedExecutionException failure) {
2927:         activeTransfers.decrementAndGet();
2928:         throw failure;
2929:       }
2930:     }
2931: 
2932:     private void transfer(java.net.Socket from, java.net.Socket to) {
2933:       byte[] bytes = new byte[8192];
2934:       try {
2935:         int count;
2936:         while ((count = from.getInputStream().read(bytes)) != -1) {
2937:           to.getOutputStream().write(bytes, 0, count);
2938:           to.getOutputStream().flush();
2939:         }
2940:       } catch (IOException disconnected) {
2941:         // JDBC completion and the explicit private route cut close both opaque sides.
2942:       } finally {
2943:         Arrays.fill(bytes, (byte) 0);
2944:         try {
2945:           closeSocket(from);
2946:           closeSocket(to);
2947:         } finally {
2948:           activeTransfers.decrementAndGet();
2949:         }
2950:       }
2951:     }
2952: 
2953:     private void closeSocket(java.net.Socket socket) {
2954:       if (socket == null) {
2955:         return;
2956:       }
2957:       try {
2958:         socket.close();
2959:       } catch (IOException failure) {
2960:         closeFailures.add(failure);
2961:       } finally {
2962:         if (socket.isClosed()) {
2963:           sockets.remove(socket);
2964:         }
2965:       }
2966:     }
