2976:           listenerFailure = failure;
2977:           if (!previous.isClosed()) {
2978:             listener = previous;
2979:           }
2980:         }
2981:       }
2982:       // Continue socket cleanup even if closing the listener failed.
2983:       for (var socket : sockets.toArray(java.net.Socket[]::new)) {
2984:         closeSocket(socket);
