2991:     @Override
2992:     public void close() throws Exception {
2993:       // Observation failures never authorize closing beneath the real sender/confirmation.
2994:       for (SourceStopOwner owner : owners) {
2995:         owner.drainUninterruptibly();
2996:       }
2997:       var failures = new java.util.ArrayList<Throwable>();
2998:       synchronized (this) {
2999:         closed = true;
3000:         try {
3001:           unavailable();
3002:         } catch (Exception | Error failure) {
3003:           failures.add(failure);
3004:         }
3005:       }
3006:       bridges.shutdownNow();
3007:       try {
3008:         if (!bridges.awaitTermination(5, TimeUnit.SECONDS)) {
3009:           failures.add(new AssertionError("Case-owned PG bridge tasks were not reaped"));
3010:         }
3011:       } catch (InterruptedException failure) {
3012:         Thread.currentThread().interrupt();
3013:         failures.add(failure);
3014:       }
3015:       IOException closeFailure;
3016:       while ((closeFailure = closeFailures.poll()) != null) {
3017:         failures.add(closeFailure);
3018:       }
3019:       if (!idle()) {
3020:         failures.add(new AssertionError("Case-owned PG sockets still have live owners"));
3021:       }
3022:       if (listener != null && !listener.isClosed()) {
3023:         failures.add(new AssertionError("Case-owned PG listener was not closed"));
3024:       }
3025:       if (!failures.isEmpty()) {
3026:         Throwable first = failures.get(0);
3027:         for (int i = 1; i < failures.size(); i++) {
3028:           if (failures.get(i) != first) {
3029:             first.addSuppressed(failures.get(i));
3030:           }
3031:         }
3032:         if (first instanceof Exception failure) {
3033:           throw failure;
3034:         }
3035:         if (first instanceof Error failure) {
3036:           throw failure;
3037:         }
3038:         throw new AssertionError(first);
3039:       }
3040:     }
