3240:   private static void relay(com.sun.net.httpserver.HttpExchange raw) throws IOException {
3241:     var exchange = (HttpsExchange) raw;
3242:     byte[] received = null;
3243:     Scenario scenario = null;
3244:     try {
3245:       assertThat(exchange.getSSLSession().getPeerCertificates().length).isGreaterThan(0);
3246:       authenticateRelay(exchange.getRequestHeaders().getFirst("Authorization"));
3247:       received = exchange.getRequestBody().readAllBytes();
3248:       JsonNode body = C.parseWire(received);
3249:       String id = body.path("sessionId").asText();
3250:       String path = exchange.getRequestURI().getPath();
3251:       boolean heldAssignmentStop = false;
3252:       if (id.isEmpty()
3253:           && path.endsWith("/stop")
3254:           && body.path("kind").asText().equals("assignment")) {
3255:         String actualAssignmentId = body.path("assignment").path("sessionId").asText();
3256:         Scenario ownedSetup = BY_SESSION.get(actualAssignmentId);
3257:         if (ownedSetup != null && ownedSetup.heldRowSetupCase) {
3258:           id = actualAssignmentId;
3259:           heldAssignmentStop = true;
3260:         }
3261:       }
3262:       scenario = BY_SESSION.get(id);
3263:       require(scenario != null, "FORBIDDEN_SCOPE", 403);
3264:       if (heldAssignmentStop) {
3265:         acceptHeldRowAssignmentStop(exchange, scenario, body, id);
3266:       } else if (path.endsWith("/assign")) {
3267:         JsonNode claimed =
3268:             callback(
3269:                 id,
3270:                 "claim",
3271:                 C.object()
3272:                     .put("schemaVersion", 3)
3273:                     .put("sessionId", id)
3274:                     .put("workerId", "worker-1")
3275:                     .put("expectedFence", body.path("expectedFence").asInt())
3276:                     .set("versions", DOCUMENTS.path("versions")));
3277:         var response =
3278:             C.object()
3279:                 .put("schemaVersion", 3)
3280:                 .put("status", "OWNED")
3281:                 .put("ownerFence", claimed.path("owner").path("fence").asInt())
3282:                 .put("leaseExpiresAt", claimed.path("owner").path("leaseExpiresAt").asText());
3283:         response.set("assignment", body);
3284:         respond(exchange, 200, response);
3285:       } else if (path.endsWith("/stop")) {
3286:         scenario.stops.incrementAndGet();
3287:         if (scenario.stopGate != null) {
3288:           scenario.stopGate.hold();
3289:         }
3290:         respond(exchange, scenario.stopStatus, identity(body));
3291:       } else if (path.endsWith("/prepare")) {
3292:         var response =
3293:             identity(body)
3294:                 .put("preparationId", UUID.randomUUID().toString())
3295:                 .put("requestDigest", body.path("requestDigest").asText())
3296:                 .put("evidenceHash", body.path("proposal").path("evidenceHash").asText())
3297:                 .put(
3298:                     "authoredInputsHash", body.path("proposal").path("authoredInputsHash").asText())
3299:                 .put("expiresAt", body.path("expiresAt").asText());
3300:         respond(exchange, 200, response);
3301:       } else if (path.endsWith("/dispatch")) {
3302:         scenario.posts.incrementAndGet();
3303:         scenario.certified.set(true);
3304:         assertThat(action(id).path("dispatchCount").asInt()).isEqualTo(1);
3305:         assertThat(scenario.reads.get()).isEqualTo(1);
3306:         assertThat(body.path("secret").path("value").asText().equals(scenario.canary)).isTrue();
3307:         ObjectNode response = identity(body);
3308:         ObjectNode ledger = body.path("ledger").deepCopy();
3309:         ledger
3310:             .put("state", scenario.mode == Mode.COMPLETE_200_OWNER_FAILED ? "FAILED" : "SUCCEEDED")
3311:             .put(
3312:                 "outcomeCode",
3313:                 scenario.mode == Mode.COMPLETE_200_OWNER_FAILED ? "TARGET_CHANGED" : "OK");
3314:         response.set("ledger", ledger);
3315:         response.putNull("availability");
3316:         if (scenario.mode.callback()) {
3317:           callback(id, "outcomes", response);
3318:           scenario.callbacks.incrementAndGet();
3319:         }
3320:         if (scenario.mode.partial()) {
3321:           exchange.sendResponseHeaders(scenario.mode.status(), 0);
3322:           try {
3323:             exchange.getResponseBody().write('{');
3324:             exchange.getResponseBody().flush();
3325:             scenario.headers.countDown();
3326:             while (true) {
3327:               exchange.getResponseBody().write(' ');
3328:               exchange.getResponseBody().flush();
3329:               Thread.sleep(20);
3330:             }
3331:           } catch (IOException cancelled) {
3332:             scenario.disconnected.countDown();
3333:           } catch (InterruptedException interrupted) {
3334:             Thread.currentThread().interrupt();
3335:           }
3336:         } else {
3337:           respond(exchange, scenario.mode.status(), response);
3338:         }
3339:       } else {
3340:         respond(exchange, 200, identity(body));
3341:       }
3342:     } catch (Throwable failure) {
3343:       if (scenario != null) {
3344:         scenario.peerFailure.set(failure);
3345:       }
3346:       try {
3347:         exchange.sendResponseHeaders(500, -1);
3348:       } catch (IOException ignored) {
3349:         /* Peer already closed. */
3350:       }
3351:     } finally {
3352:       if (received != null) {
3353:         Arrays.fill(received, (byte) 0);
3354:       }
3355:       exchange.close();
3356:     }
3357:   }
