3362:   private static void acceptHeldRowAssignmentStop(
3363:       HttpsExchange exchange, Scenario scenario, JsonNode body, String id) throws IOException {
3364:     require(scenario.heldRowSetupCase && scenario.sessionId.equals(id), "FORBIDDEN_SCOPE", 403);
3365:     require(
3366:         exchange
3367:                 .getRequestURI()
3368:                 .getPath()
3369:                 .equals("/internal/v2/studio/guided-sessions/" + id + "/stop")
3370:             && exchange.getRequestURI().getRawQuery() == null,
3371:         "INVALID_CONTRACT",
3372:         422);
3373:     var fields = new java.util.HashSet<String>();
3374:     body.fieldNames().forEachRemaining(fields::add);
3375:     require(
3376:         fields.equals(java.util.Set.of("schemaVersion", "kind", "assignment", "reason"))
3377:             && body.path("schemaVersion").isIntegralNumber()
3378:             && body.path("schemaVersion").asInt() == 3
3379:             && body.path("kind").asText().equals("assignment")
3380:             && java.util.Set.of("CANCELLED", "EXPIRED", "REVOKED", "UNKNOWN_OUTCOME")
3381:                 .contains(body.path("reason").asText()),
3382:         "INVALID_CONTRACT",
3383:         422);
3384:     C.validate("v3/assignment", body.path("assignment"));
3385:     ObjectNode actualIntent = new GuidedAssignmentStore(actualJdbc, C).find(id);
3386:     require(
3387:         actualIntent != null && actualIntent.equals(body.path("assignment")),
3388:         "FORBIDDEN_SCOPE",
3389:         403);
3390:     JsonNode actualOwner =
3391:         C.parse(
3392:             actualJdbc.queryForObject(
3393:                 "SELECT document->'owner' FROM studio_guided_sessions WHERE session_id=?",
3394:                 String.class,
3395:                 id));
3396:     require(
3397:         actualOwner.isObject()
3398:             && actualOwner.path("workerId").isTextual()
3399:             && actualOwner.path("fence").isIntegralNumber(),
3400:         "INVALID_CONTRACT",
3401:         422);
3402:     long baseFence = actualIntent.path("expectedFence").asLong();
3403:     var receipt = C.object().put("schemaVersion", 3).put("status", "STOPPED");
3404:     receipt.set("assignment", actualIntent);
3405:     if (actualOwner.path("workerId").asText().equals("unclaimed")
3406:         && actualOwner.path("fence").asLong() == baseFence) {
3407:       receipt.putNull("ownerFence").putNull("leaseExpiresAt");
3408:     } else {
3409:       require(
3410:           actualOwner.path("workerId").equals(actualIntent.path("workerId"))
3411:               && actualOwner.path("fence").asLong() == baseFence + 1
3412:               && actualOwner.path("leaseExpiresAt").isTextual(),
3413:           "STALE_FENCE",
3414:           409);
3415:       require(
3416:           !Instant.parse(actualOwner.path("leaseExpiresAt").asText())
3417:               .isAfter(Instant.parse(actualIntent.path("expiresAt").asText())),
3418:           "STALE_FENCE",
3419:           409);
3420:       receipt.set("ownerFence", actualOwner.path("fence"));
3421:       receipt.set("leaseExpiresAt", actualOwner.path("leaseExpiresAt"));
3422:     }
3423:     C.validate("v3/assignment-receipt", receipt);
3424:     scenario.stops.incrementAndGet();
3425:     scenario.assignmentTerminated.set(true);
3426:     // Same canonical HTTP200 accepted by the original backend sender; no grant/launch/renew.
3427:     respond(exchange, 200, receipt);
3428:   }
