3442:   private static String token(String role, String subject, String audience) {
3443:     try {
3444:       var claims =
3445:           C.object()
3446:               .put("iss", ISSUER_NAME)
3447:               .put("sub", subject)
3448:               .put("role", role)
3449:               .put("aud", audience)
3450:               .put("iat", Instant.now().getEpochSecond())
3451:               .put("exp", Instant.now().plusSeconds(120).getEpochSecond());
3452:       var encoder = Base64.getUrlEncoder().withoutPadding();
3453:       String input =
3454:           encoder.encodeToString(
3455:                   "{\"alg\":\"RS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8))
3456:               + "."
3457:               + encoder.encodeToString(claims.toString().getBytes(StandardCharsets.UTF_8));
3458:       var signature = Signature.getInstance("SHA256withRSA");
3459:       signature.initSign(ISSUER.getPrivate());
3460:       signature.update(input.getBytes(StandardCharsets.US_ASCII));
3461:       return input + "." + encoder.encodeToString(signature.sign());
3462:     } catch (Exception failure) {
3463:       throw new IllegalStateException("Fixture signing failed", failure);
3464:     }
