3467:   private static void authenticateRelay(String authorization) throws Exception {
3468:     require(authorization != null && authorization.startsWith("Bearer "), "UNAUTHENTICATED", 401);
3469:     String[] parts = authorization.substring(7).split("\\.");
3470:     require(parts.length == 3, "UNAUTHENTICATED", 401);
3471:     var decoder = Base64.getUrlDecoder();
3472:     var signature = Signature.getInstance("SHA256withRSA");
3473:     signature.initVerify(ISSUER.getPublic());
3474:     signature.update((parts[0] + "." + parts[1]).getBytes(StandardCharsets.US_ASCII));
3475:     require(signature.verify(decoder.decode(parts[2])), "UNAUTHENTICATED", 401);
3476:     JsonNode claims = C.parseWire(decoder.decode(parts[1]));
3477:     var fields = new java.util.HashSet<String>();
3478:     claims.fieldNames().forEachRemaining(fields::add);
3479:     require(
3480:         fields.equals(Set.of("iss", "sub", "role", "aud", "iat", "exp"))
3481:             && claims.path("iss").asText().equals(ISSUER_NAME)
3482:             && claims.path("sub").asText().equals("controller-1")
3483:             && claims.path("role").asText().equals("backend-controller")
3484:             && claims.path("aud").asText().equals("studio-guided-runner")
3485:             && claims.path("iat").asLong() <= Instant.now().getEpochSecond()
3486:             && claims.path("exp").asLong() > Instant.now().getEpochSecond(),
3487:         "UNAUTHENTICATED",
3488:         401);
3489:   }
